// O download da Meta traz só os bytes: sem nome e, às vezes, sem mime confiável.
// A transcrição do OpenAI e o upload para o Condo Manager dependem da extensão.
const EXT = {
  'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac',
  'audio/amr': 'amr', 'audio/wav': 'wav', 'audio/webm': 'webm',
  'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp',
  'video/mp4': 'mp4', 'video/3gpp': '3gp',
  'application/pdf': 'pdf',
};

const m = $('Mensagem1').item.json;
const items = $input.all();

for (const item of items) {
  const bin = item.binary?.data;
  if (!bin) continue;

  const mime = ((m.mimetype || bin.mimeType || '').split(';')[0] || '').trim();
  const ext = EXT[mime] ?? (mime.split('/')[1] || 'bin');

  bin.mimeType = mime || bin.mimeType;
  bin.fileExtension = ext;
  bin.fileName = `${m.media_id || m.message_id}.${ext}`;
}

return items;

