  const mime = ((m.mimetype || bin.mimeType || '').split(';')[0] || '').trim();
  const ext = EXT[mime] ?? (mime.split('/')[1] || 'bin');

  bin.mimeType = mime || bin.mimeType;
  bin.fileExtension = ext;
  bin.fileName = `${m.media_id || m.message_id}.${ext}`;
}

return items;

// Monta o texto que o agente vai ler, já com o que foi extraído da mídia.
const m = $('Mensagem1').item.json;
const legenda = m.caption ? ` A legenda era: "${m.caption}".` : '';

// O nó de visão devolve formatos diferentes conforme a versão: a v1 (Chat Completions) entrega
// { content }, a v2 (Responses API) entrega { output: [ {type:'reasoning'}, {type:'message', ...} ] }.
const descricaoDaFoto = () => {
  const j = $('Analisar imagem1').item.json;
  if (typeof j.content === 'string') return j.content;

  const saida = Array.isArray(j.output) ? j.output : [];
  const texto = saida
    .filter((o) => o.type === 'message')
    .flatMap((o) => o.content ?? [])
    .filter((c) => c.type === 'output_text')
    .map((c) => c.text)
    .join('\n')
    .trim();

  // Orçamento de tokens consumido inteiro pelo raciocínio devolve mensagem vazia: é melhor
  // o agente saber que a foto chegou e não pôde ser descrita do que receber "undefined".
  return texto || 'não consegui descrever a foto';
};

const texto = {
  texto:     () => m.text,
  audio:     () => $('Transcrever1').item.json.text,
  imagem:    () => `[O morador enviou uma foto. Descrição automática: ${descricaoDaFoto()}]${legenda}`,
  video:     () => `[O morador enviou um vídeo, que eu não consigo assistir.${legenda}]`,
  documento: () => `[O morador enviou um documento, que eu não consigo ler.${legenda}]`,
}[m.kind]();

return [{ json: { ...$('dados1').item.json, message: texto } }];

// A mensagem que o agente lê é a rajada inteira, não o último pedaço dela.
// Em avaliação o buffer é pulado e a mensagem chega direto de "Texto da mensagem1".
return [{ json: { ...$('dados1').item.json, message: $json.content ?? $json.message } }];

// O nó de transcrição devolve só o resultado e descarta o binário do item.
// O upload para /api/v1/media precisa dos dois: o texto vem daqui, o arquivo vem de "Audio binario".
// first() e não item(): a passagem pelo nó de IA quebra o pareamento, e cada execução
// trata uma mensagem só.
const arquivo = $('Audio binario1').first();

return [{ json: $input.first().json, binary: arquivo.binary }];

// O nó de análise devolve só o resultado e descarta o binário do item.
// O upload para /api/v1/media precisa dos dois: o texto vem daqui, o arquivo vem de "Imagem binaria".
// first() e não item(): a passagem pelo nó de IA quebra o pareamento, e cada execução
// trata uma mensagem só.
const arquivo = $('Imagem binaria1').first();

return [{ json: $input.first().json, binary: arquivo.binary }];

// Transforma a linha do dataset no payload que o WhatsApp Trigger entrega, para o caso
// passar pelo mesmo caminho de uma mensagem real a partir do nó Mensagem1.
const caso = $json;
const wa_id = caso.telefone.replace(/\D/g, '');
return [{ json: {
  field: 'messages',
  messaging_product: 'whatsapp',
  metadata: { display_phone_number: '', phone_number_id: 'evaluation' },
  contacts: [{ wa_id, profile: { name: '' } }],
  messages: [{
    from: wa_id,
    id: `eval-${caso.caso}-${$execution.id}`,
    timestamp: String(Math.floor(Date.now() / 1000)),
    type: 'text',
    text: { body: caso.mensagem },
  }],
}}];

// Na avaliação o histórico vem do dataset; no atendimento real, de GET /conversations.
if (!$('Evaluation Trigger').isExecuted) {
  return $input.all();
}
const caso = $('Evaluation Trigger').first().json;
let messages = [];
try {
  messages = caso.historico ? JSON.parse(caso.historico) : [];
} catch (e) {
  throw new Error(`historico inválido no caso ${caso.caso}: ${e.message}`);
}
return [{ json: { messages, pending_media: [] }, pairedItem: { item: 0 } }];

// Métricas determinísticas (0 a 1) a partir do caso e do que o fluxo fez.
const caso = $('Evaluation Trigger').first().json;
const r = $json;
const lista = (s) => (s ?? '').split(',').map((x) => x.trim()).filter(Boolean);
const chamadas = new Set(lista(r.ferramentas));

// rota_esperada aceita alternativas: "bloqueado|agente".
const rota_correta = lista((caso.rota_esperada || 'agente').replace(/\|/g, ',')).includes(r.rota) ? 1 : 0;

// Cada item de ferramentas_esperadas precisa ter sido chamado; "a|b" aceita qualquer uma.
const grupos = lista(caso.ferramentas_esperadas).map((g) => g.split('|'));
const ferramentas_esperadas = grupos.length
  ? grupos.filter((g) => g.some((t) => chamadas.has(t))).length / grupos.length
  : 1;

const proibidas = lista(caso.ferramentas_proibidas).filter((t) => chamadas.has(t));
const ferramentas_proibidas = proibidas.length ? 0 : 1;

// Formato de WhatsApp: nada de JSON, nome de tool, código HTTP/erro, markdown pesado ou textão.
const TOOLS = ['verificar_morador', 'consultar_regimento', 'consultar_comunicados', 'abrir_chamado', 'listar_chamados',
  'consultar_chamado', 'listar_areas', 'consultar_disponibilidade', 'reservar_area', 'listar_reservas', 'cancelar_reserva', 'escalar_humano'];
const ERROS = /\b(HTTP|erro|error|status)\s*(4\d\d|5\d\d)\b|resident_not_found|validation_error|slot_unavailable|advance_notice_violation|ticket_not_found|unit\.id|area_id|slot_id/i;
const texto = r.resposta ?? '';
const problemas = [];
if (!texto.trim()) problemas.push('vazia');
if (/[{\[]\s*"/.test(texto)) problemas.push('json');
if (TOOLS.some((t) => texto.includes(t))) problemas.push('nome de ferramenta');
if (ERROS.test(texto)) problemas.push('código interno');
if (/^#{1,6}\s|\*\*/m.test(texto)) problemas.push('markdown');
if (texto.length > 700) problemas.push(`longa (${texto.length})`);
const formato = problemas.length ? 0 : 1;

return [{ json: {
  ...r,
  rota_correta,
  ferramentas_esperadas,
  ferramentas_proibidas,
  formato,
  diagnostico: [
    rota_correta ? null : `rota ${r.rota}, esperada ${caso.rota_esperada}`,
    ferramentas_esperadas < 1 ? `faltou: ${grupos.filter((g) => !g.some((t) => chamadas.has(t))).map((g) => g.join('|')).join(', ')}` : null,
    proibidas.length ? `chamou proibida: ${proibidas.join(', ')}` : null,
    problemas.length ? `formato: ${problemas.join(', ')}` : null,
  ].filter(Boolean).join(' · ') || 'ok',
}}];

